CREATE OR REPLACE FUNCTION public.decidir_solicitacao_acesso(p_admin_id bigint, p_solicitacao_id numeric, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_solicitacao record;
  v_usuarios_afetados bigint;
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA403', MESSAGE = 'Acesso recusado.';
  END IF;

  IF p_admin_id IS NULL
     OR p_admin_id <= 0
     OR p_admin_id > 9007199254740991 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA403', MESSAGE = 'Ator invalido.';
  END IF;

  IF p_solicitacao_id IS NULL
     OR p_solicitacao_id <= 0
     OR p_solicitacao_id::text IN ('NaN', 'Infinity', '-Infinity')
     OR p_solicitacao_id <> pg_catalog.trunc(p_solicitacao_id)
     OR p_status IS NULL
     OR p_status COLLATE pg_catalog."C"
        NOT IN ('aprovado', 'rejeitado') THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA400', MESSAGE = 'Entrada invalida.';
  END IF;

  -- Identidade deve vir do backend autenticado.
  PERFORM u.id
    FROM public.usuarios AS u
   WHERE u.id = p_admin_id
     AND u.perfil = 'admin';

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA403', MESSAGE = 'Acesso recusado.';
  END IF;

  IF p_solicitacao_id > 2147483647 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA404', MESSAGE = 'Solicitacao ausente.';
  END IF;

  SELECT s.usuario_id, s.perfil_solicitado, s.status
    INTO v_solicitacao
    FROM public.solicitacoes_acesso AS s
   WHERE s.id = p_solicitacao_id::integer
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA404', MESSAGE = 'Solicitacao ausente.';
  END IF;

  IF v_solicitacao.status IS DISTINCT FROM
     'pendente'::public.solicitacoes_acesso_status_enum THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TA409', MESSAGE = 'Solicitacao ja analisada.';
  END IF;

  IF p_status = 'aprovado' THEN
    UPDATE public.usuarios
       SET perfil =
         (v_solicitacao.perfil_solicitado::text)::public.usuarios_perfil_enum
     WHERE id = v_solicitacao.usuario_id
       AND perfil = 'participante';

    GET DIAGNOSTICS v_usuarios_afetados = ROW_COUNT;

    IF v_usuarios_afetados <> 1 THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TA412',
        MESSAGE = 'Perfil atual incompativel.';
    END IF;
  END IF;

  -- Rejeição não modifica nem restringe o perfil atual.
  UPDATE public.solicitacoes_acesso
     SET status = p_status::public.solicitacoes_acesso_status_enum
   WHERE id = p_solicitacao_id::integer;

  RETURN pg_catalog.jsonb_build_object(
    'mensagem',
    CASE WHEN p_status = 'aprovado'
      THEN 'Solicitação aprovada com sucesso!'
      ELSE 'Solicitação rejeitada com sucesso!'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.publicar_cotacao(p_evento_id bigint, p_usuario_id bigint, p_prazo text, p_hoje_utc text, p_observacoes text, p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_item jsonb;
  v_normalizados jsonb := '[]'::jsonb;
  v_persistidos jsonb := '[]'::jsonb;
  v_categoria text;
  v_descricao text;
  v_valor text;
  v_custo record;
  v_id bigint;
  v_prazo date;
  v_hoje date;

  v_espacos constant text :=
    U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
BEGIN
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP403', MESSAGE = 'Acesso recusado.';
  END IF;

  IF p_evento_id IS NULL
     OR p_evento_id <= 0
     OR p_evento_id > 9007199254740991
     OR p_usuario_id IS NULL
     OR p_usuario_id <= 0
     OR p_usuario_id > 9007199254740991 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP400', MESSAGE = 'Identificador invalido.';
  END IF;

  IF p_itens IS NULL
     OR pg_catalog.jsonb_typeof(p_itens) <> 'array' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP400', MESSAGE = 'Lista de custos invalida.';
  END IF;

  -- Validação integral antes de bloquear ou escrever.
  -- Decimais chegam normalizados em texto pelo adaptador.
  FOR v_item IN
    SELECT j.value
      FROM pg_catalog.jsonb_array_elements(p_itens)
        WITH ORDINALITY AS j(value, ordem)
     ORDER BY j.ordem
  LOOP
    IF pg_catalog.jsonb_typeof(v_item) <> 'object'
       OR pg_catalog.jsonb_typeof(v_item -> 'categoria')
          IS DISTINCT FROM 'string'
       OR pg_catalog.jsonb_typeof(v_item -> 'descricao')
          IS DISTINCT FROM 'string'
       OR pg_catalog.jsonb_typeof(v_item -> 'valor_estimado')
          IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TP400', MESSAGE = 'Item de custo invalido.';
    END IF;

    v_categoria :=
      pg_catalog.btrim(v_item ->> 'categoria', v_espacos);
    v_descricao :=
      pg_catalog.btrim(v_item ->> 'descricao', v_espacos);
    v_valor := v_item ->> 'valor_estimado';

    IF pg_catalog.char_length(v_categoria) NOT BETWEEN 1 AND 100
       OR pg_catalog.char_length(v_descricao) NOT BETWEEN 1 AND 255
       OR v_valor !~ '^(0|[1-9][0-9]{0,9})[.][0-9]{2}$' THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TP400', MESSAGE = 'Item de custo invalido.';
    END IF;

    v_normalizados := v_normalizados ||
      pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'categoria', v_categoria,
          'descricao', v_descricao,
          'valor_estimado', v_valor
        )
      );
  END LOOP;

  -- Dia UTC capturado pelo backend antes de esperar locks.
  -- Identidade e dia confiável não devem vir do corpo público.
  IF p_prazo IS NULL
     OR p_hoje_utc IS NULL
     OR p_observacoes IS NULL
     OR p_prazo !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR p_hoje_utc !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP400', MESSAGE = 'Data invalida.';
  END IF;

  BEGIN
    v_prazo := p_prazo::date;
    v_hoje := p_hoje_utc::date;
  EXCEPTION
    WHEN SQLSTATE '22007' OR SQLSTATE '22008' THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TP401', MESSAGE = 'Prazo invalido.';
  END;

  IF pg_catalog.to_char(v_prazo, 'YYYY-MM-DD') <> p_prazo
     OR pg_catalog.to_char(v_hoje, 'YYYY-MM-DD') <> p_hoje_utc
     OR v_prazo < v_hoje THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP401',
      MESSAGE = 'Prazo passado ou invalido.';
  END IF;

  PERFORM u.id
    FROM public.usuarios AS u
   WHERE u.id = p_usuario_id
     AND u.perfil = 'organizador';

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP403', MESSAGE = 'Acesso recusado.';
  END IF;

  -- Ordem compatível com substituição: evento → custos → escritas.
  PERFORM e.id
    FROM public.eventos AS e
   WHERE e.id = p_evento_id
     AND e.usuario_id = p_usuario_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP404', MESSAGE = 'Evento ausente.';
  END IF;

  FOR v_custo IN
    SELECT c.id, c.categoria, c.descricao, c.valor_estimado
      FROM public.custos_evento AS c
     WHERE c.evento_id = p_evento_id
     ORDER BY c.id
     FOR UPDATE
  LOOP
    v_categoria :=
      pg_catalog.btrim(v_custo.categoria, v_espacos);
    v_descricao :=
      pg_catalog.btrim(v_custo.descricao, v_espacos);
    v_valor := v_custo.valor_estimado::text;

    IF v_categoria IS NULL
       OR v_descricao IS NULL
       OR v_valor IS NULL
       OR pg_catalog.char_length(v_categoria) NOT BETWEEN 1 AND 100
       OR pg_catalog.char_length(v_descricao) NOT BETWEEN 1 AND 255
       OR v_valor !~ '^(0|[1-9][0-9]{0,9})[.][0-9]{2}$' THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TP500',
        MESSAGE = 'Custos persistidos invalidos.';
    END IF;

    v_persistidos := v_persistidos ||
      pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'categoria', v_categoria,
          'descricao', v_descricao,
          'valor_estimado', v_valor
        )
      );
  END LOOP;

  IF pg_catalog.jsonb_array_length(v_persistidos) = 0 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP402', MESSAGE = 'Sem custos.';
  END IF;

  -- Comparação exata dos itens normalizados, incluindo ordem.
  IF v_normalizados::text COLLATE pg_catalog."C"
     IS DISTINCT FROM
     v_persistidos::text COLLATE pg_catalog."C" THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TP409', MESSAGE = 'Revisao divergente.';
  END IF;

  INSERT INTO public.cotacoes (
    evento_id, prazo, modalidade, observacoes, status
  )
  VALUES (
    p_evento_id, v_prazo, 'Fechada', p_observacoes, 'Aberta'
  )
  RETURNING id INTO v_id;

  -- Itens exclusivamente dos custos persistidos.
  FOR v_item IN
    SELECT j.value
      FROM pg_catalog.jsonb_array_elements(v_persistidos)
        WITH ORDINALITY AS j(value, ordem)
     ORDER BY j.ordem
  LOOP
    INSERT INTO public.itens_cotacao (
      cotacao_id, categoria, descricao, valor_estimado
    )
    VALUES (
      v_id,
      v_item ->> 'categoria',
      v_item ->> 'descricao',
      (v_item ->> 'valor_estimado')::numeric(12,2)
    );
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'id', v_id,
    'evento_id', p_evento_id,
    'prazo', p_prazo,
    'modalidade', 'Fechada',
    'observacoes', p_observacoes,
    'status', 'Aberta',
    'itens', v_persistidos
  );

  -- Falhas nas escritas propagam e revertem a publicação inteira.
END;
$function$

CREATE OR REPLACE FUNCTION public.substituir_custos_evento(p_evento_id bigint, p_usuario_id bigint, p_custos jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_item jsonb;
  v_normalizados jsonb := '[]'::jsonb;
  v_categoria text;
  v_descricao text;
  v_valor text;
  v_resultado jsonb;

  -- Mesmo whitespace do String.trim do ECMAScript.
  v_espacos constant text :=
    U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF';
BEGIN
  -- Identidade fornecida pelo backend autenticado.
  IF current_user <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TC403', MESSAGE = 'Acesso recusado.';
  END IF;

  IF p_evento_id IS NULL
     OR p_evento_id <= 0
     OR p_evento_id > 9007199254740991
     OR p_usuario_id IS NULL
     OR p_usuario_id <= 0
     OR p_usuario_id > 9007199254740991 THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TC400', MESSAGE = 'Identificador invalido.';
  END IF;

  IF p_custos IS NULL
     OR pg_catalog.jsonb_typeof(p_custos) <> 'array' THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TC400', MESSAGE = 'Lista de custos invalida.';
  END IF;

  -- Validação integral antes de bloquear ou escrever.
  -- Dinheiro recebido em texto normalizado.
  FOR v_item IN
    SELECT j.value
      FROM pg_catalog.jsonb_array_elements(p_custos)
        WITH ORDINALITY AS j(value, ordem)
     ORDER BY j.ordem
  LOOP
    IF pg_catalog.jsonb_typeof(v_item) <> 'object'
       OR pg_catalog.jsonb_typeof(v_item -> 'categoria')
          IS DISTINCT FROM 'string'
       OR pg_catalog.jsonb_typeof(v_item -> 'descricao')
          IS DISTINCT FROM 'string'
       OR pg_catalog.jsonb_typeof(v_item -> 'valor_estimado')
          IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TC400', MESSAGE = 'Item de custo invalido.';
    END IF;

    v_categoria :=
      pg_catalog.btrim(v_item ->> 'categoria', v_espacos);
    v_descricao :=
      pg_catalog.btrim(v_item ->> 'descricao', v_espacos);
    v_valor := v_item ->> 'valor_estimado';

    IF pg_catalog.char_length(v_categoria) NOT BETWEEN 1 AND 100
       OR pg_catalog.char_length(v_descricao) NOT BETWEEN 1 AND 255
       OR v_valor !~ '^(0|[1-9][0-9]{0,9})[.][0-9]{2}$' THEN
      RAISE EXCEPTION USING
        ERRCODE = 'TC400', MESSAGE = 'Item de custo invalido.';
    END IF;

    v_normalizados := v_normalizados ||
      pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'categoria', v_categoria,
          'descricao', v_descricao,
          'valor_estimado', v_valor
        )
      );
  END LOOP;

  PERFORM u.id
    FROM public.usuarios AS u
   WHERE u.id = p_usuario_id
     AND u.perfil = 'organizador';

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TC403', MESSAGE = 'Acesso recusado.';
  END IF;

  -- Primeiro bloqueio: evento, compartilhado com publicação.
  PERFORM e.id
    FROM public.eventos AS e
   WHERE e.id = p_evento_id
     AND e.usuario_id = p_usuario_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = 'TC404', MESSAGE = 'Evento nao encontrado.';
  END IF;

  DELETE FROM public.custos_evento
   WHERE evento_id = p_evento_id;

  FOR v_item IN
    SELECT j.value
      FROM pg_catalog.jsonb_array_elements(v_normalizados)
        WITH ORDINALITY AS j(value, ordem)
     ORDER BY j.ordem
  LOOP
    INSERT INTO public.custos_evento (
      evento_id, categoria, descricao, valor_estimado
    )
    VALUES (
      p_evento_id,
      v_item ->> 'categoria',
      v_item ->> 'descricao',
      (v_item ->> 'valor_estimado')::numeric(12,2)
    );
  END LOOP;

  -- Releitura na mesma transação; decimais em texto.
  SELECT COALESCE(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', c.id,
        'evento_id', c.evento_id,
        'categoria', c.categoria,
        'descricao', c.descricao,
        'valor_estimado', c.valor_estimado::text
      )
      ORDER BY c.id
    ),
    '[]'::jsonb
  )
    INTO v_resultado
    FROM public.custos_evento AS c
   WHERE c.evento_id = p_evento_id;

  RETURN v_resultado;
  -- Falhas propagam e abortam a transação inteira.
END;
$function$
